        inputs.add("clientA");
        inputs.add("192.168.0.1##VN0");
        inputs.add("中文测试");
        inputs.add("￿�");
        Random r = new Random(42);
        for (int i = 0; i < 20000; i++) {
            StringBuilder sb = new StringBuilder();
            int len = r.nextInt(40);
            for (int j = 0; j < len; j++) sb.append((char) r.nextInt(0x10000));
            inputs.add(sb.toString());
        }
        int bad = 0;
        for (String s : inputs) {
            int x = (Integer) ref.invoke(null, s);
            int y = (Integer) mine.invoke(null, s);
            if (x != y) { bad++; if (bad < 5) System.out.println("MISMATCH " + x + " vs " + y); }
        }
        System.out.println("compared=" + inputs.size() + " mismatches=" + bad);

        String[] servers = {"192.168.0.1", "10.0.0.7", "172.16.5.9"};
        TreeMap<Integer, String> ring = new TreeMap<>();
        for (String s : servers)
            for (int i = 0; i < 10; i++) {
                String vn = s + "##VN" + i;
                ring.put((Integer) mine.invoke(null, vn), vn);
            }
        System.out.println("ring size=" + ring.size());
        for (Map.Entry<Integer, String> e : ring.entrySet())
            System.out.println("  " + e.getKey() + " -> " + e.getValue());
        for (String c : new String[]{"clientA", "clientB", "clientC", "client1", "zzz"}) {
            int h = (Integer) mine.invoke(null, c);
            SortedMap<Integer, String> tail = ring.tailMap(h);
            String expect = tail.isEmpty() ? "(EMPTY-TAIL -> NPE in original)" : tail.get(tail.firstKey());
            System.out.println(c + " hash=" + h + " expectedNode=" + expect);
        }
    }
